const input = $input.first().json;
const toIso = (date) => date.toISOString();
const now = new Date(input.now_utc);
let windows = [];
if (input.mode === 'backfill') {
  const start = new Date(input.backfill.start_utc);
  const end = new Date(input.backfill.end_utc);
  const maxMs = input.policy.max_days_per_backfill_run * 24 * 60 * 60 * 1000;
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || start >= end || end - start > maxMs) {
    return [{ json: { ...input, status: 'failed', errors: [{ code: 'G8N_SCHEDULE_INVALID_BACKFILL_WINDOW', masked: true }] } }];
  }
  for (let cursor = start; cursor < end; cursor = new Date(cursor.getTime() + input.policy.sub_window_hours * 3600000)) {
    const subEnd = new Date(Math.min(cursor.getTime() + input.policy.sub_window_hours * 3600000, end.getTime()));
    windows.push({ window_start_utc: toIso(cursor), window_end_utc: toIso(subEnd), status: 'planned' });
  }
} else {
  const checkpointEnd = input.previous_checkpoint?.last_successful_window_end_utc ? new Date(input.previous_checkpoint.last_successful_window_end_utc) : new Date(now.getTime() - input.policy.default_lookback_hours_when_no_checkpoint * 3600000);
  const start = new Date(checkpointEnd.getTime() - input.policy.overlap_minutes * 60000);
  windows.push({ window_start_utc: toIso(start), window_end_utc: toIso(now), status: 'planned' });
}
return [{ json: { ...input, windows } }];

const input = $input.first().json;
const locked = Boolean(input.existing_lock && input.existing_lock.status === 'started');
const windows = (input.windows || []).map((window) => ({ ...window, lock_key: `${input.source}:${window.window_start_utc}:${window.window_end_utc}`, status: locked ? 'skipped_locked' : 'started', watermark_can_advance: false }));
return [{ json: { ...input, status: locked ? 'skipped_locked' : 'started', windows, next_step: 'Delegate each started window to WF-10/WF-11/WF-20/WF-21 locally. Advance watermark only after completed status.' } }];
